import { useState, useEffect } from "react";
import RavaCRM from "./RavaCRM.jsx";
import PanelSusana from "./PanelSusana.jsx";
import PanelProfesional from "./PanelProfesional.jsx";

const LOGO_BASE64 = "data:image/jpeg;base64,";

// ══════════════════════════════════════════
// USUARIOS
// ══════════════════════════════════════════
const USUARIOS = {
  admin:    { password: "sodapedetoPu334$", role: "admin",      nombre: "Juan",      profesional: null },
  susana:   { password: "Campeon2026$",     role: "susana",     nombre: "Susana",    profesional: null },
  isolina:  { password: "Corrientes2026$",  role: "profesional",nombre: "Isolina",   profesional: "ISOLINA" },
  juancruz: { password: "Moron2026$",       role: "profesional",nombre: "Juan Cruz", profesional: "JUAN CRUZ" },
  paula:    { password: "Santafe2026$",     role: "profesional",nombre: "Paula",     profesional: "PAULA" },
  francisco:{ password: "Lujan2026$",       role: "profesional",nombre: "Francisco", profesional: "FRANCISCO" },
  daniela:  { password: "Bauti2026$",       role: "profesional",nombre: "Daniela",   profesional: "DANIELA" },
};

// ══════════════════════════════════════════
// LOGIN
// ══════════════════════════════════════════
function Login({ onLogin }) {
  const [usuario, setUsuario] = useState("");
  const [password, setPassword] = useState("");
  const [mostrarPwd, setMostrarPwd] = useState(false);
  const [error, setError] = useState("");
  const [cargando, setCargando] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setCargando(true);
    await new Promise(r => setTimeout(r, 400));

    const key = usuario.toLowerCase().trim();
    const user = USUARIOS[key];

    if (user && user.password === password) {
      onLogin({ username: key, ...user });
    } else if (!USUARIOS[key]) {
      setError("Usuario no encontrado. Verificá que esté bien escrito.");
    } else {
      setError("Contraseña incorrecta. Verificá mayúsculas y caracteres especiales.");
    }
    setCargando(false);
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "linear-gradient(135deg, #0a1628 0%, #0d2347 50%, #0a1628 100%)",
      display: "flex", alignItems: "center", justifyContent: "center",
      padding: "1rem", fontFamily: "'Segoe UI', system-ui, sans-serif",
      position: "relative", overflow: "hidden",
    }}>
      {/* Fondo con puntos */}
      <div style={{
        position: "fixed", inset: 0, opacity: 0.03,
        backgroundImage: "radial-gradient(circle at 1px 1px, #7fff00 1px, transparent 0)",
        backgroundSize: "28px 28px", pointerEvents: "none",
      }}/>

      <div style={{
        background: "rgba(255,255,255,0.05)",
        backdropFilter: "blur(20px)",
        border: "1px solid rgba(127,255,0,0.15)",
        borderRadius: "28px",
        padding: "2.5rem 2rem",
        width: "100%", maxWidth: "400px",
        boxShadow: "0 32px 80px rgba(0,0,0,0.6), 0 0 0 1px rgba(127,255,0,0.08)",
      }}>
        {/* Logo */}
        <div style={{ textAlign: "center", marginBottom: "2rem" }}>
          <div style={{
            width: "110px", height: "110px", borderRadius: "50%",
            margin: "0 auto 1.25rem",
            overflow: "hidden",
            boxShadow: "0 8px 32px rgba(0,0,0,0.5), 0 0 0 3px rgba(127,255,0,0.3)",
          }}>
            <img src={LOGO_BASE64} alt="Kinesiología Rava" style={{ width: "100%", height: "100%", objectFit: "cover" }}/>
          </div>
          <h1 style={{ color: "white", fontSize: "1.35rem", fontWeight: 700, margin: 0, letterSpacing: "-0.3px" }}>
            Kinesiología Rava
          </h1>
          <p style={{ color: "rgba(127,255,0,0.7)", fontSize: "0.8rem", marginTop: "0.3rem", letterSpacing: "0.08em" }}>
            SISTEMA DE GESTIÓN INTERNA
          </p>
        </div>

        <form onSubmit={handleSubmit}>
          {/* Usuario */}
          <div style={{ marginBottom: "1rem" }}>
            <label style={{ color: "rgba(255,255,255,0.6)", fontSize: "0.75rem", fontWeight: 600, display: "block", marginBottom: "0.4rem", letterSpacing: "0.06em", textTransform: "uppercase" }}>
              Usuario
            </label>
            <input
              type="text"
              value={usuario}
              onChange={e => setUsuario(e.target.value)}
              placeholder="Ingresá tu usuario"
              required
              autoCapitalize="none"
              style={{
                width: "100%", padding: "0.85rem 1rem",
                background: "rgba(255,255,255,0.07)",
                border: "1px solid rgba(255,255,255,0.12)",
                borderRadius: "12px", color: "white",
                fontSize: "1rem", outline: "none", boxSizing: "border-box",
              }}
              onFocus={e => e.target.style.borderColor = "rgba(127,255,0,0.5)"}
              onBlur={e => e.target.style.borderColor = "rgba(255,255,255,0.12)"}
            />
            <p style={{ color: "rgba(255,255,255,0.3)", fontSize: "0.7rem", marginTop: "0.3rem" }}>
              Podés escribirlo en mayúsculas o minúsculas
            </p>
          </div>

          {/* Contraseña */}
          <div style={{ marginBottom: "1.5rem" }}>
            <label style={{ color: "rgba(255,255,255,0.6)", fontSize: "0.75rem", fontWeight: 600, display: "block", marginBottom: "0.4rem", letterSpacing: "0.06em", textTransform: "uppercase" }}>
              Contraseña
            </label>
            <div style={{ position: "relative" }}>
              <input
                type={mostrarPwd ? "text" : "password"}
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="••••••••••"
                required
                style={{
                  width: "100%", padding: "0.85rem 3rem 0.85rem 1rem",
                  background: "rgba(255,255,255,0.07)",
                  border: "1px solid rgba(255,255,255,0.12)",
                  borderRadius: "12px", color: "white",
                  fontSize: "1rem", outline: "none", boxSizing: "border-box",
                }}
                onFocus={e => e.target.style.borderColor = "rgba(127,255,0,0.5)"}
                onBlur={e => e.target.style.borderColor = "rgba(255,255,255,0.12)"}
              />
              <button
                type="button"
                onClick={() => setMostrarPwd(!mostrarPwd)}
                title={mostrarPwd ? "Ocultar contraseña" : "Ver contraseña"}
                style={{
                  position: "absolute", right: "0.85rem", top: "50%",
                  transform: "translateY(-50%)",
                  background: "none", border: "none",
                  color: mostrarPwd ? "rgba(127,255,0,0.8)" : "rgba(255,255,255,0.35)",
                  cursor: "pointer", fontSize: "1.2rem", padding: 0,
                  transition: "color 0.2s",
                }}
              >
                {mostrarPwd ? "🙈" : "👁️"}
              </button>
            </div>
          </div>

          {/* Error */}
          {error && (
            <div style={{
              background: "rgba(239,68,68,0.12)",
              border: "1px solid rgba(239,68,68,0.3)",
              color: "#fca5a5", padding: "0.75rem 1rem",
              borderRadius: "10px", fontSize: "0.85rem",
              marginBottom: "1rem", textAlign: "center",
            }}>
              ⚠️ {error}
            </div>
          )}

          <button
            type="submit"
            disabled={cargando}
            style={{
              width: "100%", padding: "0.9rem",
              background: cargando
                ? "rgba(127,255,0,0.3)"
                : "linear-gradient(135deg, #7fff00, #5fdf00)",
              border: "none", borderRadius: "12px",
              color: "#0a1628", fontSize: "1rem",
              fontWeight: 700, cursor: cargando ? "not-allowed" : "pointer",
              boxShadow: "0 4px 20px rgba(127,255,0,0.25)",
              transition: "all 0.2s",
            }}
          >
            {cargando ? "Ingresando..." : "Ingresar →"}
          </button>
        </form>

        <p style={{
          color: "rgba(255,255,255,0.2)", fontSize: "0.72rem",
          textAlign: "center", marginTop: "1.75rem",
        }}>
          ¿Problemas para ingresar? Contactá a Juan
        </p>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════
// APP PRINCIPAL
// ══════════════════════════════════════════
export default function App() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    try {
      const saved = sessionStorage.getItem("rava_user");
      if (saved) setUser(JSON.parse(saved));
    } catch {}
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    try { sessionStorage.setItem("rava_user", JSON.stringify(userData)); } catch {}
  };

  const handleLogout = () => {
    setUser(null);
    try { sessionStorage.removeItem("rava_user"); } catch {}
  };

  if (!user) return <Login onLogin={handleLogin} />;

  if (user.role === "admin")      return <RavaCRM user={user} onLogout={handleLogout} />;
  if (user.role === "susana")     return <PanelSusana user={user} onLogout={handleLogout} />;
  return <PanelProfesional user={user} onLogout={handleLogout} />;
}
